create or replace function "rollups"."readings_hourly_refresh"("from" timestamptz) returns void language sql set search_path = pg_catalog, pg_temp set timezone = 'UTC' as $buckets$
with fresh as (
  select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", count(*) as "events"
  from public.readings as c
  where c."taken_at" >= date_trunc('hour', $1)
  group by 1, 2
), gone as (
  delete from "public"."readings_hourly" as r where r."bucket" >= date_trunc('hour', $1) and not exists (select from fresh where fresh."bucket" = r."bucket" and fresh."org_id" = r."org_id")
)
insert into "public"."readings_hourly" ("bucket", "org_id", "events")
select "bucket", "org_id", "events" from fresh
on conflict ("bucket", "org_id") do update set "events" = excluded."events"
$buckets$;

